import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import pg from "pg";

/** Forward migrations, generated by drizzle-kit, live in apps/api/drizzle. */
const migrationsFolder = fileURLToPath(new URL("../../drizzle", import.meta.url));
/** Hand-written rollbacks (RNF-20), one `<tag>.down.sql` per forward migration. */
const rollbackFolder = fileURLToPath(new URL("../../drizzle-down", import.meta.url));

/** Applies pending migrations. Idempotent: already-applied migrations are skipped. */
export async function runMigrations(databaseUrl: string): Promise<void> {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 1 });
  try {
    await migrate(drizzle(pool), { migrationsFolder });
  } finally {
    await pool.end();
  }
}

function migrationTagsInOrder(): string[] {
  const journal = JSON.parse(
    readFileSync(join(migrationsFolder, "meta", "_journal.json"), "utf8"),
  ) as { entries: Array<{ tag: string }> };
  return journal.entries.map((entry) => entry.tag);
}

/**
 * Rolls back the most recently applied migrations, one at a time, newest first.
 * Each step runs its hand-written down script and removes its journal row in one
 * transaction, so a failed step leaves the database as it was.
 */
export async function rollbackMigrations(databaseUrl: string, steps: number): Promise<void> {
  const tags = migrationTagsInOrder();
  const client = new pg.Client({ connectionString: databaseUrl });
  await client.connect();
  try {
    for (let step = 0; step < steps; step += 1) {
      const journalExists = await client.query<{ present: boolean }>(
        `select to_regclass('drizzle.__drizzle_migrations') is not null as present`,
      );
      const applied = journalExists.rows[0]?.present
        ? await client.query<{ count: string }>(
            `select count(*)::text as count from drizzle.__drizzle_migrations`,
          )
        : undefined;
      const count = Number(applied?.rows[0]?.count ?? 0);
      if (count === 0) {
        throw new Error("rollback refused: no applied migrations left");
      }
      const tag = tags[count - 1];
      if (!tag) {
        throw new Error(`rollback refused: journal has ${count} entries but ${tags.length} tags`);
      }
      const downSql = readFileSync(join(rollbackFolder, `${tag}.down.sql`), "utf8");

      await client.query("begin");
      try {
        await client.query(downSql);
        await client.query(
          `delete from drizzle.__drizzle_migrations
           where id = (select max(id) from drizzle.__drizzle_migrations)`,
        );
        await client.query("commit");
      } catch (error) {
        await client.query("rollback");
        throw error;
      }
    }
  } finally {
    await client.end();
  }
}

/**
 * Drops and recreates the public schema. Refuses any database whose name does
 * not end in `_test`, so a development database can never be wiped by mistake.
 */
export async function resetDatabase(databaseUrl: string): Promise<void> {
  const databaseName = new URL(databaseUrl).pathname.replace(/^\//, "");
  if (!databaseName.endsWith("_test")) {
    throw new Error(`resetDatabase refuses to reset "${databaseName}": name must end in _test`);
  }

  const client = new pg.Client({ connectionString: databaseUrl });
  await client.connect();
  try {
    // "drizzle" holds the migration journal; it must go too, or the migrator would
    // believe migrations are already applied and skip them.
    await client.query("drop schema if exists drizzle cascade");
    await client.query("drop schema if exists public cascade");
    await client.query("create schema public");
  } finally {
    await client.end();
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    process.stderr.write("DATABASE_URL is required to run migrations\n");
    process.exit(1);
  }
  runMigrations(databaseUrl)
    .then(() => {
      process.stdout.write("migrations applied\n");
    })
    .catch((error: unknown) => {
      process.stderr.write(`migration failed: ${String(error)}\n`);
      process.exit(1);
    });
}
